\label{decomposition_THM}
		Let $k$ be a field finitely generated over a separably closed field. We consider a proper morphism $f\colon X \rightarrow Y$ of finite type $k$-schemes $X$ and $Y$. Let $K \in \textnormal{D}^b_{c}(X)$ be an arithmetic semisimple complex on $X$.
		The pushforward $f_*(K)$ is semisimple.

\label{unibranchClass_RMK}
	Let $X$ be a geometrically unibranch $k$-scheme, and $k'/k$ an arbitrary field extension. The scheme $X_{k'}$ is geometrically unibranch by \cite[Prop.~6.15.7]{EGA4}. In particular, if $X_{k'}$ is connected, $\ell$-adic representations of the etale fundamental group of $\pi_1(X_{k'})$ correspond to lisse $\ell$-adic sheaves by \cite[Lem.~7.4.10]{BhattSPE}. 

	Recall that the arithmetic and the geometric monodromy group of a lisse $\overline{\mathbb{Q}}_\ell$-sheaf $F$ on a scheme $X$ as above is the Zariski closure of $\pi_1(X)$ and $\pi_1(X_{\overline{k}})$ in $\mathbf{GL}(F)$ respectively.

\label{model_DEF}
	Let $X$ be a  $k$-scheme and $k_0 \subseteq k$ a subfield. A \textit{model of $X$ over $k_0$} is a $k_0$-scheme $X'$ with a fixed isomorphism $\alpha\colon X \rightarrow X'_{k}$. 

	Let $K \in\textnormal{D}^b_{c}(X)$ be a complex. If $X'$ is a model of $X$ over $k_0$, then a \textit{model of $K$ on $X'$} is a complex $K' \in \textnormal{D}^b_{c}(X')$ together with a fixed isomorphism $\alpha^*(K'_k) \rightarrow K$. We say $K$ \textit{admits a model over $k_0$} if there exists a model $X'$ of $X$ over $k_0$ such that there exists a model of $K$ on $X'$.

\label{independence_RMK}
	Let $X$ be a $k$-scheme. If a complex on $X$ admits a model over an arithmetic field, then it is arithmetic. In particular, a semisimple geometric complex (see \cite[{}6.2.4]{BBD}) is arithmetic.

	The condition of being arithmetic is independent of the implicitly chosen model by Remark \ref{uniquenessmodels_REM} in the following sense. Let $K \in \textnormal{D}^b_{c}(X)$ be an arithmetic complex and $X'$ a model of $X$ over a field $k_0$. There exists a finitely generated extension $k_1/k_0$ with $k_1 \subseteq k$ such that the action of $\textnormal{Aut}(\overline{k}/k_1)$ has a finite orbit when acting on the isomorphism class of $K_{\overline{k}}$.

\label{subquotientsarithmetic_THM}
	Let $X$ be a $k$-scheme an $K \in \textnormal{D}^b_{c}(X)$ an arithmetic complex. We have the following:
	\begin{enumerate}[]\item The perverse cohomology sheaves ${}^\mathfrak{p}\mathscr{H}^{n}(K)$ are arithmetic for all $n \in \mathbb{Z}$.
		\item Any irreducible subquotient of ${}^\mathfrak{p}\mathscr{H}^{n}(K)_{\overline{k}}$ is arithmetic for all $n \in \mathbb{Z}$. 	
	 \end{enumerate}

\label{lefschetzprinciple_LEM}
	Let $X$ be a $k$-scheme and $K \in \textnormal{D}^b_{c}(X)$. Suppose $X'$ is a model of $X$ over a field $k_0 \subseteq k$. There exists a finitely generated field extension $k_1/k_0$ with $k_1 \subseteq \overline{k}$ such that $K_{\overline{k}}$ admits a model on $X'_{\overline{k}_1}$.

	Given an extension $k_1/k_0$ with $k_1 \subseteq \overline{k}$ such that $K_{\overline{k}}$ admits a model on $X'_{\overline{k}_1}$, then the model is unique up to unique isomorphism.

\label{irred_LEM}
		Let $k_0$ be a field and $S_0$ a connected regular $k_0$-scheme with function field $k$ of dimension $d$. Let $X_0$ be an $S_0$-scheme and $M \in \textnormal{Perv}(X_0)$.
		\begin{enumerate}[]\item Suppose $M$ is universally locally acyclic over $S_0$. Then $M_k[-d]$ is irreducible if and only if $M$ is irreducible.
		\item If $M$ is geometrically semisimple, then the restriction to the generic fiber $M_k[-d]$ is semisimple.
		\end{enumerate}

\label{extensionari_THM}
	Let $S_0$ be an integral arithmetic scheme with function field $k$ and $X_0$ a $S_0$-scheme. Let $M \in \textnormal{Perv}(X_k)$ be a geometrically irreducible perverse sheaf.
	\begin{enumerate}
		\item  There exists a dense open subscheme $U_0 \subseteq S_0$ and $M_0 \in \textnormal{Perv}^{\textnormal{ULA}}(X_0/U_0)$ such that the restriction of $M_0$ to the generic fiber is isomorphic to $M$. 
		\item Suppose $U_0$ is geometrically unibranch. The extension $M_0$ is unique up to unique isomorphism. 





	\end{enumerate}

\label{qunimon_PROP}
		Let $X_0$ be a topologically Noetherian scheme. We assume that no finite extension of any residue field of any point of $X_0$ contains all $\ell$'th roots of unity. Let $K \in \textnormal{D}^b_c(X_0)$ be a complex with an $I_\ell$-action.
		\begin{enumerate}
			\item The action by $I_\ell$ is quasi-unipotent. 
			\item There exists a functorial nilpotent monodromy operator
			\[
			N\colon K(1) \rightarrow K.
			\]
		\end{enumerate}

\label{prolnc_REM}
		When $S_0$ is a strict trait, the above definition computes the part of the nearby cycles on which the inertia acts through the maximal pro-$\ell$ quotient. The Kummer map provides an isomorphism $I_{S_0}^\ell = I_\ell(s)$ since $s$ is separably closed. The $I_\ell$-action on the pro-$\ell$ nearby cycles identifies with the action of the maximal pro-$\ell$ quotient of inertia on the nearby cycles along this isomorphism.

		In general, the formation of the pro-$\ell$ nearby cycles commutes with base change along weakly etale morphisms by weakly etale base change. In particular, the pro-$\ell$ nearby cycles compare to the pro-$\ell$ nearby cycles on the strict henselization. This relates the pro-$\ell$ nearby cycles to the usual nearby cycles. For example, this implies that the pro-$\ell$ nearby cycles are constructible when the nearby cycles are constructible over the strict henselization.

\label{kashiwara_THM}
		Let $S$ be the strict henselization of a discrete valuation ring essentially of finite type over a field. Let $X$ be an $S$-scheme and $M \in \textnormal{Perv}(X_{{\eta}})$ a geometrically semisimple arithmetic perverse sheaf on the generic fiber.
		\begin{enumerate}
			\item The graded piece of the monodromy filtration $\textnormal{Gr}^M_n(\Psi^{\textnormal{uni}}(M))$ is geometrically semisimple for all $n \in \mathbb{Z}$. 
			\item Let $f\colon X \rightarrow Y$ be a proper morphism of $S$-schemes. The monodromy spectral sequence
			\[
			E_1^{pq} := {}^\mathfrak{p}\mathscr{H}^{p + q}(f_*(\textnormal{Gr}_{-q}^M(\Psi^{\textnormal{uni}}(M)))) \Rightarrow {}^\mathfrak{p}\mathscr{H}^{p + q}(f_*(\Psi^{\textnormal{uni}}(M)))
			\]
			degenerates on the second page. Moreover, the morphism $f$ satisfies the monodromy property with respect to $\Psi^{\textnormal{uni}}(M)$. 
		\end{enumerate}

\label{liftinglemma_LEM}
		 Let $G$ be a profinite group and $\mathbf{G}$ an algebraic group over $\overline{\mathbb{Q}}_\ell$. Suppose $\mathbf{H} \subseteq \mathbf{G}$ is a normal algebraic subgroup of $\mathbf{G}$ and we are given a continuous map $G \rightarrow \mathbf{G}/\mathbf{H}$. We assume $\mathbf{H}^0$ is a torus. There exists an open subgroup $U \subseteq G$ and a continuous  map $U \rightarrow \mathbf{G}$ fitting into the diagram 
				\[

				\begin{tikzcd}
						U \arrow[r] \arrow[d, dashed] & G \arrow[d] \\
						\mathbf{G} \arrow[r]                   & \mathbf{G}/\mathbf{H}.         
					\end{tikzcd}
				\]
		If $G \rightarrow \mathbf{G}/\mathbf{H}$ is a group morphism, then we can choose $U \rightarrow \mathbf{G}$ to be a group morphism.

\label{fibfuncperv_THM}
	Let $X$ be a $k$-scheme. There exists a faithful, exact, and $\overline{\mathbb{Q}}_\ell$-linear functor to the category of finite dimensional $\overline{\mathbb{Q}}_\ell$-vector spaces
	\[
	\textnormal{Perv}(X) \rightarrow \overline{\mathbb{Q}}_\ell-\textnormal{fdVec}
	\]

\label{genbc_THM}
	Let $f\colon X \rightarrow Y$ be a finitely presented morphism of qcqs schemes. We assume one of the following two conditions on the coefficient ring $R$:
	\begin{enumerate}
		\item The ring $R$ is a Noetherian ring complete with respect to an ideal $I \subset R$. We assume the characteristic of $R/I$ is invertible on $Y$.
		\item The ring $R$ is $R = \overline{\mathbb{Q}}_\ell$ for a prime $\ell$ invertible on $Y$.
	\end{enumerate}
	Let $K \in \textnormal{D}^b_c(X, R)$. There exists a finite constructible partition
	\[
	Y = \bigsqcup_{i = 1}^n Y_i
	\]
	such that all $1 \leq i \leq n$ satisfy: 
	\begin{enumerate}
		\item The pushforward $f_*(K|_{Y_i})$ is constructible over $Y_i$.
		\item The formation of the pushforward $f_*(K|_{Y_i})$ commutes with any base-change $Y' \rightarrow Y_i$.
	\end{enumerate}

\label{genbchom_THM}
	Let $f\colon X \rightarrow Y$ be a finitely presented morphism of qcqs schemes. We assume one of the following two conditions on the coefficient ring $R$:
	\begin{enumerate}
		\item The ring $R$ is a complete Noetherian local ring. We assume the characteristic of the residue field of $R$ is invertible on $Y$.
		\item The ring $R$ is $\overline{\mathbb{Q}}_\ell$ for a prime $\ell$ invertible on $Y$.
	\end{enumerate}
	Let $K, L \in \textnormal{D}^b_c(X, R)$ be two constructible complexes. There exists a constructible finite partition
	\[
	Y = \bigsqcup_{i = 1}^n Y_i
	\]
	such that all $1 \leq i \leq n$ satisfy: 
	\begin{enumerate}
		\item The internal mapping object $\textnormal{Hom}(K|_{Y_i}, L|_{Y_i}) \in \textnormal{D}^b_c(X_{Y_i}, R)$ exists. 
		\item The formation of the internal mapping object $\textnormal{Hom}(K|_{Y_i}, L|_{Y_i})$ commutes with base-change $Y' \rightarrow Y_i$. 
	\end{enumerate}

The comparison functor is fully faithful for bounded below complexes by \cite[Prop.~5.2.6]{BhattSPE}. Thus we obtain
	\begin{align*}
		\textnormal{Hom}_{\Lambda}(K, \textnormal{Hom}_{\Lambda, \textnormal{cl}}(L, L')) &= \textnormal{Hom}_{\Lambda, \textnormal{cl}}(K, \textnormal{Hom}_{\Lambda, \textnormal{cl}}(L, L')) \\
		&= \textnormal{Hom}_{\Lambda, \textnormal{cl}}(K\otimes_{\Lambda, \textnormal{cl}} L, L') \\
		&= \textnormal{Hom}_{\Lambda}(K\otimes_{\Lambda, \textnormal{cl}} L, L').
	\end{align*}
	We have
	\begin{align*}
		K\otimes_{\Lambda, \textnormal{cl}} L = K\otimes_{\Lambda} L,
	\end{align*}
	hence the claim.
